// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.createGameItem("test", "ipfs://test", true, true, 100, 1 ether, 10);

        address alice = address(0x123);
        address bob = address(0x456);

        vm.prank(alice);
        c.setApprovalForAll(bob, true);

        assertTrue(c.isApprovedForAll(alice, bob));

        c.adjustAdminAccess(address(this), false);

        bool result = c.isApprovedForAll(alice, bob);
        assertTrue(result);
    }
}
